#!/usr/bin/env node
/**
 * accept-snapshots — accepts generator Verify snapshots whose diff is purely cosmetic (a licence
 * header, a "Generated by …/Feature v*" line), and lists every other one so a human looks at it.
 *
 * A snapshot that changed for a real reason is the whole point of having snapshots, so those are
 * never accepted here.
 *
 *   node scripts/accept-snapshots.mjs             accept cosmetic diffs, list the rest
 *   node scripts/accept-snapshots.mjs --all       accept everything — only when establishing a
 *                                                 baseline, never to make a red suite green
 *   node scripts/accept-snapshots.mjs --dry-run   report what it would do
 */
import { copyFileSync, unlinkSync, readFileSync, existsSync, readdirSync } from "node:fs";
import { join } from "node:path";

const args = process.argv.slice(2);
const acceptAll = args.includes("--all");
const dryRun = args.includes("--dry-run");

// The only differences a diff may contain and still count as header-only.
const COSMETIC_PATTERNS = [
  /^\s*\/\/\s*Copyright\s*\(c\)/,
  /^\s*\/\/\s*Licensed under/,
  /^\s*\/\/\s*See LICENSE/,
  /^\s*\/\/\s*Generated by Pragmatic/,
];

// Walked in Node rather than shelled out. An execSync running `git ls-files ...; find . -name ...`
// with `2>/dev/null` is a POSIX pipeline: on Windows it goes through cmd.exe, where none of that
// means what it says, and the script dies before doing anything. A tool a contributor cannot run is
// not a tool.
const SKIP = new Set(["node_modules", "bin", "obj", ".git", ".vs", "dist", "artifacts"]);

function findReceived(dir, out = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (!SKIP.has(entry.name)) findReceived(join(dir, entry.name), out);
    } else if (entry.name.endsWith(".received.txt")) {
      out.push(join(dir, entry.name));
    }
  }
  return out;
}

const uniq = findReceived(".");

let accepted = 0, kept = [];
for (const r of uniq) {
  const v = r.replace(/\.received\.txt$/, ".verified.txt");
  if (!existsSync(v)) continue;
  let isCosmetic = false;
  if (acceptAll) {
    isCosmetic = true;
  } else {
    // compute diff via Node (no exec overhead per file)
    const a = readFileSync(v, "utf8").split(/\r?\n/);
    const b = readFileSync(r, "utf8").split(/\r?\n/);
    // crude line-set diff: lines in one but not the other
    const aSet = new Set(a), bSet = new Set(b);
    const onlyA = a.filter(l => !bSet.has(l));
    const onlyB = b.filter(l => !aSet.has(l));
    const allDiffs = [...onlyA, ...onlyB];
    isCosmetic = allDiffs.length > 0 && allDiffs.every(l => l.trim() === "" || COSMETIC_PATTERNS.some(p => p.test(l)));
  }
  if (isCosmetic) {
    if (!dryRun) { copyFileSync(r, v); unlinkSync(r); }
    accepted++;
  } else {
    kept.push(r);
  }
}

console.log(JSON.stringify({ dry_run: dryRun, accept_all: acceptAll, received_total: uniq.length, accepted_cosmetic: accepted, kept_for_review: kept.length, samples: kept.slice(0, 5) }, null, 2));
